import React, { HTMLProps, useCallback, useRef, useState, useImperativeHandle } from 'react';

import InputWrapper, { InputWrapperProps } from '../InputWrapper';
import {
  PasswordControl,
  StyledInputPassword,
  PasswordInputContainer,
} from './InputPassword.styles';

export interface InputPasswordProps
  extends Omit<HTMLProps<HTMLInputElement>, 'children' | 'size' | 'css'>,
    Omit<InputWrapperProps, 'children' | 'counter' | 'maxCounter'> {
  size?: 'medium';
  width?: string | number;
  passwordControls?: {
    show: string;
    hide: string;
  };
}

export const InputPassword = React.forwardRef(
  (
    {
      hint,
      label,
      legend,
      hasError,
      disabled = false,
      errorText,
      labelProps,
      value: valueFromProps,
      onChange: onChangeFromProps,
      defaultValue,
      size,
      placeholder = 'Placeholder text',
      id,
      passwordControls = {
        show: 'Show',
        hide: 'Hide',
      },
      width,
      ...otherProps
    }: InputPasswordProps,
    forwardedRef: React.ForwardedRef<HTMLInputElement>
  ): JSX.Element => {
    const isControlled = valueFromProps !== undefined;
    const hasDefaultvalue = defaultValue !== undefined;
    const [value, setValue] = useState(() =>
      hasDefaultvalue ? (defaultValue as string)?.toString() : ''
    );
    const mappedValue = isControlled ? (valueFromProps as string)?.toString() : value;
    const [focused, setFocused] = useState(false);

    const innerRef = useRef<HTMLInputElement>(null);
    useImperativeHandle(forwardedRef, () => innerRef?.current as HTMLInputElement);

    const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (onChangeFromProps && typeof onChangeFromProps === 'function') {
        onChangeFromProps(e);
        if (!isControlled) setValue(e.target.value);
        return;
      }
      setValue(e.target.value);
    };

    const [showPassword, setShowPassword] = useState<boolean>(false);

    const togglePassword = useCallback(() => {
      setShowPassword((controlPassword) => !controlPassword);
    }, []);

    return (
      <InputWrapper
        labelProps={{ ...labelProps, htmlFor: id }}
        label={label}
        hint={hint}
        legend={legend}
        hasError={hasError}
        disabled={disabled}
        required
        errorText={errorText}
        width={width}
      >
        <PasswordInputContainer focused={focused} size={size} hasError={hasError}>
          <StyledInputPassword
            {...otherProps}
            ref={innerRef}
            value={mappedValue}
            onChange={onChange}
            disabled={disabled}
            onFocus={() => !hasError && setFocused(true)}
            onBlur={() => setFocused(false)}
            size={size}
            placeholder={placeholder}
            id={id}
            type={!showPassword ? 'password' : 'text'}
          />
          <PasswordControl
            onClick={() => !disabled && togglePassword()}
            disabled={disabled}
            hasError={hasError}
            size={size}
          >
            {showPassword ? passwordControls.hide : passwordControls.show}
          </PasswordControl>
        </PasswordInputContainer>
      </InputWrapper>
    );
  }
);

export default InputPassword;
